package org.apache.commons.jxpath.ri.model.dom;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.assertFalse;

import java.util.Locale;

import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.DocumentBuilderFactory;

import org.apache.commons.jxpath.ri.QName;
import org.apache.commons.jxpath.ri.compiler.NodeNameTest;
import org.apache.commons.jxpath.ri.compiler.NodeTypeTest;
import org.apache.commons.jxpath.ri.Compiler;
import org.junit.Test;
import org.w3c.dom.Document;
import org.w3c.dom.Element;
import org.w3c.dom.Node;

import java.io.ByteArrayInputStream;
import org.xml.sax.InputSource;

public class DOMNodePointerTest {

    private Document parse(String xml) throws Exception {
        DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();
        dbf.setNamespaceAware(true);
        DocumentBuilder db = dbf.newDocumentBuilder();
        return db.parse(new InputSource(new ByteArrayInputStream(xml.getBytes("UTF-8"))));
    }

    @Test
    public void testGetNamespaceURIExplicit() throws Exception {
        Document doc = parse("<root xmlns:a='urn:a'><a:child/></root>");
        Element root = doc.getDocumentElement();
        Node child = root.getFirstChild();
        DOMNodePointer pointer = new DOMNodePointer(child, Locale.getDefault());
        assertEquals("urn:a", pointer.getNamespaceURI());
    }

    @Test
    public void testGetNamespaceURINoNamespace() throws Exception {
        Document doc = parse("<root><child/></root>");
        Element root = doc.getDocumentElement();
        Node child = root.getFirstChild();
        DOMNodePointer pointer = new DOMNodePointer(child, Locale.getDefault());
        assertNull(pointer.getNamespaceURI());
    }

    @Test
    public void testGetPrefixAndLocalName() throws Exception {
        Document doc = parse("<root xmlns:a='urn:a'><a:child/></root>");
        Element root = doc.getDocumentElement();
        Node child = root.getFirstChild();
        assertEquals("a", DOMNodePointer.getPrefix(child));
        assertEquals("child", DOMNodePointer.getLocalName(child));
    }

    @Test
    public void testTestNodeWithWildcardName() throws Exception {
        Document doc = parse("<root><child/></root>");
        Element root = doc.getDocumentElement();
        Node child = root.getFirstChild();
        NodeNameTest wildcard = new NodeNameTest(new QName(null, "*"));
        assertTrue(DOMNodePointer.testNode(child, wildcard));
    }

    @Test
    public void testTestNodeTypeText() throws Exception {
        Document doc = parse("<root>text</root>");
        Element root = doc.getDocumentElement();
        Node textNode = root.getFirstChild();
        NodeTypeTest textTest = new NodeTypeTest(Compiler.NODE_TYPE_TEXT);
        assertTrue(DOMNodePointer.testNode(textNode, textTest));
        NodeTypeTest commentTest = new NodeTypeTest(Compiler.NODE_TYPE_COMMENT);
        assertFalse(DOMNodePointer.testNode(textNode, commentTest));
    }

    @Test
    public void testIsLeafAndLength() throws Exception {
        Document doc = parse("<root><child/><child/></root>");
        Element root = doc.getDocumentElement();
        DOMNodePointer rootPointer = new DOMNodePointer(root, Locale.getDefault());
        assertFalse(rootPointer.isLeaf());
        assertEquals(1, rootPointer.getLength());

        Node leafChild = root.getFirstChild();
        DOMNodePointer leafPointer = new DOMNodePointer(leafChild, Locale.getDefault());
        assertTrue(leafPointer.isLeaf());
    }

    @Test
    public void testIsCollectionAlwaysFalse() throws Exception {
        Document doc = parse("<root/>");
        Element root = doc.getDocumentElement();
        DOMNodePointer pointer = new DOMNodePointer(root, Locale.getDefault());
        assertFalse(pointer.isCollection());
    }
}
